-- Tenant membership and row-level security baseline. Review alongside the core schema before applying.
create table if not exists public.company_memberships(
 id uuid primary key default gen_random_uuid(),
 company_id uuid not null references public.companies(id) on delete cascade,
 user_id uuid not null references auth.users(id) on delete cascade,
 role text not null check(role in('owner','admin','manager','staff','viewer')),
 created_at timestamptz not null default now(),
 unique(company_id,user_id)
);
alter table public.company_memberships enable row level security;
create policy "members can read own memberships" on public.company_memberships for select using(user_id=auth.uid());
create policy "company admins manage memberships" on public.company_memberships for all
 using(exists(select 1 from public.company_memberships m where m.company_id=company_memberships.company_id and m.user_id=auth.uid() and m.role in('owner','admin')))
 with check(exists(select 1 from public.company_memberships m where m.company_id=company_memberships.company_id and m.user_id=auth.uid() and m.role in('owner','admin')));
\nalter table public.branches enable row level security;\ncreate policy "tenant members access branches" on public.branches for all using (exists(select 1 from public.company_memberships m where m.company_id=branches.company_id and m.user_id=auth.uid())) with check (exists(select 1 from public.company_memberships m where m.company_id=branches.company_id and m.user_id=auth.uid()));\n\nalter table public.stock_items enable row level security;\ncreate policy "tenant members access stock_items" on public.stock_items for all using (exists(select 1 from public.company_memberships m where m.company_id=stock_items.company_id and m.user_id=auth.uid())) with check (exists(select 1 from public.company_memberships m where m.company_id=stock_items.company_id and m.user_id=auth.uid()));\n\nalter table public.intake_batches enable row level security;\ncreate policy "tenant members access intake_batches" on public.intake_batches for all using (exists(select 1 from public.company_memberships m where m.company_id=intake_batches.company_id and m.user_id=auth.uid())) with check (exists(select 1 from public.company_memberships m where m.company_id=intake_batches.company_id and m.user_id=auth.uid()));\n\nalter table public.yield_records enable row level security;\ncreate policy "tenant members access yield_records" on public.yield_records for all using (exists(select 1 from public.company_memberships m where m.company_id=(select b.company_id from public.intake_batches b where b.id=yield_records.batch_id) and m.user_id=auth.uid())) with check (exists(select 1 from public.company_memberships m where m.company_id=(select b.company_id from public.intake_batches b where b.id=yield_records.batch_id) and m.user_id=auth.uid()));\n\nalter table public.stock_movements enable row level security;\ncreate policy "tenant members access stock_movements" on public.stock_movements for all using (exists(select 1 from public.company_memberships m where m.company_id=stock_movements.company_id and m.user_id=auth.uid())) with check (exists(select 1 from public.company_memberships m where m.company_id=stock_movements.company_id and m.user_id=auth.uid()));\n\nalter table public.audit_events enable row level security;\ncreate policy "tenant members access audit_events" on public.audit_events for all using (exists(select 1 from public.company_memberships m where m.company_id=audit_events.company_id and m.user_id=auth.uid())) with check (exists(select 1 from public.company_memberships m where m.company_id=audit_events.company_id and m.user_id=auth.uid()));\n